public Response getUser(String id) {
    Response response = given()
            .baseUri("https://qa-api.shop.example.com")
            .contentType("application/json")
            .header("X-Api-Key", "secret")
            .when()
            .get(USERS + id);
    response.then().statusCode(200);
    return response;
}

public Response createUser(String first, String last, String email, String phone, String city, boolean admin) {
    String body = "{\"first\":\"" + first + "\",\"last\":\"" + last + "\",\"email\":\"" + email + "\"}";
    return given()
            .baseUri("https://qa-api.shop.example.com")
            .contentType("application/json")
            .header("X-Api-Key", "secret")
            .body(body)
            .when()
            .post("/users")
            .then().statusCode(201)
            .extract().response();
}

public Response fetchUser(String userId) {
    System.out.println("Fetching user " + userId);
    Response res = RestAssured.given()
            .baseUri("https://qa-api.shop.example.com")
            .contentType("application/json")
            .header("X-Api-Key", "secret")
            .when()
            .get("/users/" + userId);
    res.then().statusCode(200);
    return res;
}

public void deleteUser(String userId) {
    RestAssured.given()
            .baseUri("https://qa-api.shop.example.com")
            .header("X-Api-Key", "secret")
            .delete("/users/" + userId);
}

